/**
* @example
* int a = 1;
*/
// stdlib-c-doctest disable
int myFunction() {
	return 1;
}

/**
* @example
* char *s = "\"escaped quote";
* char *t = "double \\\" escape";
* int c = 3;
* // returns 3
*/
int validFunction() { // stdlib-c-doctest disable
	return 3;
}

/**
* @example
* int d = extractedFunction();
* // returns 4
*/
int extractedFunction() {
	return 4;
}
